fn solve(s: Vec<char>) -> &'static str {
    // Stack to simulate pair removals
    let mut stack: Vec<char> = Vec::with_capacity(s.len());
    // parity == true means we have removed an odd number of pairs so far
    let mut parity = false;

    for c in s {
        // If the top of the stack equals the current char, we remove that pair
        if stack.last() == Some(&c) {
            stack.pop();
            parity = !parity;
        } else {
            stack.push(c);
        }
    }

    if parity { "Yes" } else { "No" }
}

